from bs4 import BeautifulSoup
import requests
import re

def xss_test(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')
    for tag in soup.find_all(True):
        if 'src' in tag.attrs:
            src = tag['src']
            if src.startswith('http'):
                xss_test(src)
            else:
                print('XSS vulnerability found in ' + tag.name + ' tag with src=' + src)
        elif 'href' in tag.attrs:
            href = tag['href']
            if href.startswith('http'):
                xss_test(href)
            else:
                print('XSS vulnerability found in ' + tag.name + ' tag with href=' + href)

url = 'http://example.com'
xss_test(url)
```

