#include <stdio.h>
#include <stdlib.h>
#include <time.h>

void draw_rainbow() {
    // Define the colors for the rainbow
    // Black, Red, Orange, Yellow, Green, Blue, Indigo, Violet
    // ANSI escape codes: \033[30m for black, \033[31m for red, ..., \033[37m for white
    // We will use: Black, Red, Orange, Yellow, Green, Cyan, Blue, Magenta, White
    // But for the rainbow, we will use: Red, Orange, Yellow, Green, Blue, Indigo, Violet, Red

    // Set the random seed
    srand((unsigned int)time(NULL));

    // Define the colors
    int colors[] = {31, 33, 32, 34, 36, 34, 35, 31};

    // Draw the rainbow
    for (int i = 0; i < 7; i++) {
        // Print the color
        printf("\033[2%dm", colors[i]);
        for (int j = 0; j < i; j++) {
            printf("*");
        }
        printf("\n");
    }

    // Reset the color
    printf("\033[0m");
}

int main() {
    draw_rainbow();
    return 0;
}
