### 4. Подключение к Vue

```ts
<script setup lang="ts">
import { ref } from 'vue';
import { YandexMaps } from 'yandex-maps';

const yandexMaps = new YandexMaps({
  apiKey: 'ВАШ_КЛЮЧ_КАРТОВ',
  container: 'yandexMap',
});

const map = ref(null);
const markers = ref<YandexMaps.Mark[]>();

function addMarker coordinats: [number, number] {
  const marker = yandexMaps.addMarker({
    coordinates: coordinats,
    title: 'Маркер',
  });
  markers.value.push(marker);
}
</script>
```

