```

### 2. Импортируйте и настройте Leaflet

```vue
<script setup lang="ts">
import * as Leaflet from "leaflet";
import { SFCJSProvider } from '@vue/sfcjs';
import type { MapOptions } from 'leaflet';

// Для типов
type MapOptions = {
  center: [number, number],
  zoom: number,
  layers: string[],
  options: {
    attribution: '&copy; OpenStreetMap contributors'
  }
};
</script>
```

### 3. Подключение слоя Yandex Maps

```vue
<script setup lang="ts">
import * as Leaflet from "leaflet";
import { SFCJSProvider } from '@vue/sfcjs';
import type { MapOptions } from 'leaflet';

// 1. Подключение Yandex Maps
const yandexKey = process.env.NYAMAP_API_KEY; // или используйте свой способ хранения API-ключа

// 2. Создание Map
const map = new Map();
map.setProvider(new SFCJSProvider({
  apiKey: yandexKey,
  sfcOptions: { isSfc enabled: true }
}));

const options = {
  attribution: '&copy; OpenStreetMap contributors'
};

// 3. Добавление слоя Yandex Maps
const layer = new Leaflet.MapLayer('yandex', {
  options,
  center: [55.75, 37.62], // пример координат Москвы
  zoom: 12,
  // map: map, // если нужно использовать собственную Map, иначе просто используйте map.addLayer(layer)
});

// 4. Добавление слоя в Map
map.addLayer(layer);
</script>
```

### 4. Вставьте картинку на страницу

