### `draw_rainbow.c`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#define RAINBOW_COLORS 7

// Colores básicos del arcoíris
int rainbow_colors[RAINBOW_COLORS] = {
    // Magenta, Cian, Amarillo, Verde, Azul, Índigo, Violeta
    35,  12,  10,  22,  24,  40,  21
};

// Dibujar un círculo de un color dado en la posición (x, y)
void draw_circle(int x, int y, int color) {
    printf("\033[2%d;%dH", y, x); // Establecer el cursor en la posición
    printf("\033[0%dK", color);    // Establecer el color del fondo
    printf("\033[2%d;%dH", y, x); // Volver a establecer el cursor
}

// Dibujar un arcoíris en la parte inferior de la consola
void draw_rainbow(int rows, int cols) {
    int y = rows - 1; // Parte inferior
    int x0 = cols / 2 - 5; // Centro
    int x1 = cols / 2 + 5; // Largura del punto

    // Bucle para dibujar segmentos de arcoíris
    for (int i = 0; i < RAINBOW_COLORS; i++) {
        int angle = (i * 360 / RAINBOW_COLORS);
        double rad = angle * M_PI / 180.0;
        int x = (int)(x0 * cos(rad) + x1 * sin(rad));
        int y_c = (int)(y + (x - x0) * 1.5); // Hacerlo más grueso

        draw_circle(x, y_c, rainbow_colors[i]);
        sleep(0.15); // Ralentizar para ver el arcoíris
    }
}

int main() {
    struct termios t;
    int ch;

    // Habilitar colores de fondo (solo Linux, Windows WSL o terminales personalizados)
    if (tctflag & VISCERA) tctflag &= ~VISCERA;
    if (tcflag & IANAL) tcflag &= ~IANAL;
    if (tcflag & ICANON) tcflag &= ~ICANON;
    if (tcflag & ISCTTY) tcflag &= ~ISCTTY;

    if (tcgetattr(0, &t) != 0) return 1;

    t.c_lflag &= ~ICANON | ~ECHO;
    t.c_kflag |= IANAL | VISCERA;
    t.c_cflag &= ~CSIZE;
    t.c_cflag |= CS8;
    t.c_lflag &= ~ISCTTY;
    t.c_lflag |= ICANON;

    if (tcsetattr(0, TCSANOW, &t) != 0) return 1;

    // Tamaño de la consola
    struct winsize w;
    if (getwinsize(0, &w) != 0) {
        int rows = w.h;
        int cols = w.w;
        draw_rainbow(rows, cols);
        return 0;
    }

    // Valor predeterminado
    int rows = 24, cols = 80;
    draw_rainbow(rows, cols);

    return 0;
}
